def _validate_request(data, auth_token):
    """Validate request inputs before any request data is processed."""
    # Reject malformed credentials without passing them to the token validator.
    if not isinstance(auth_token, str) or not auth_token.strip():
        raise PermissionError("invalid auth token")

    if not is_valid_token(auth_token):
        raise PermissionError("invalid auth token")

    # Do not use a truthiness check here: empty request payloads may be valid.
    if data is None:
        raise ValueError("request data is required")


def handle_request(data, auth_token):
    """Authenticate, validate, and process an incoming API request."""
    _validate_request(data, auth_token)
    return process(data)

